package ama.transcript;
import ama.access.MeetingAccess;import ama.config.ConfigArchiveSource;import ama.contract.ConfigArchiveContracts.*;import ama.contract.ConfigArchiveContracts.Ref;import ama.contract.MinutesContracts.*;import ama.storage.FileRegistry;import java.util.*;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
/** Actual three projection methods; provenance and command-readiness seams are substituted explicitly. */
class Task11ReadinessProjectionTest {
 static final String M=Task11PublicationWriteGuardBoundaryTest.MEETING,H="a".repeat(64);static final ama.contract.IdentityContracts.Actor ACTOR=Task11PublicationWriteGuardBoundaryTest.ACTOR;
 @Test void threeProjectionsDispatchReadOnlyPredicatesAndPreserveImmutableFacts()throws Exception{run(true);}
 @Test void missingRealCompositionHasOneAccurateReason()throws Exception{run(false);}
 @SuppressWarnings("unchecked") void run(boolean installed)throws Exception{
  var f=new Task11PublicationWriteGuardBoundaryTest.Fixture();var registry=mock(FileRegistry.class);when(f.authority.fileRegistry()).thenReturn(registry);when(f.authority.transactionRunner()).thenReturn(f.tx);
  var root=new LinkedHashMap<String,Object>(Map.of("id",M,"revision",1L,"access_revision",2L,"materials_pending",0L));var discovery=new MinutesGraphDiscovery.Discovery(M,"CANDIDATE",M,root,Map.of(),Map.of(),Set.of("owner"),List.of(),null);var cells=new ArrayList<Cell>();for(var column:Table.GENERATION_INPUT.columns())cells.add(column.kind()==CellKind.UINT?new UIntCell(1):new TextCell(column.name().equals("input_fingerprint")?H:column.name().equals("scope")?"FULL":M));var input=new FullRow(Table.GENERATION_INPUT,cells);var candidate=Map.<String,Object>of("id",M,"input_id",M,"task_id",M,"minutes_revision_id",M,"element_set_id",M,"base_revision",1L,"input_fingerprint",H,"state","PENDING");var graph=new MinutesGraphCapture.Graph(discovery,List.of(input),Map.of("generation_candidate",List.of(candidate)));var snapshot=mock(JdbcMinutesFactsReader.Snapshot.class);when(snapshot.graph()).thenReturn(graph);when(snapshot.observation()).thenReturn(root);when(snapshot.roots()).thenReturn(List.of());when(snapshot.generationManifestJson(M)).thenReturn("immutable-original");var facts=mock(StoredProvenanceFacts.class);when(facts.rows()).thenReturn(List.of(input));when(snapshot.facts()).thenReturn(facts);
  var editor=mock(MinutesEditorRuntime.class);var initial=mock(JdbcMinutesInitialSettings.class);var generation=mock(JdbcMinutesGenerationCommands.class);var saved=mock(JdbcMinutesSavedCommands.class);when(editor.saved()).thenReturn(saved);
  try(var readers=mockConstruction(JdbcMinutesFactsReader.class,(reader,context)->when(reader.readOwner(eq(ACTOR),eq(M),anyString(),nullable(String.class),any(TranscriptAcquisitionBudget.Ledger.class))).thenReturn(snapshot));var pages=mockConstruction(MinutesMetadataPages.class,(page,context)->when(page.allTaskRows(eq(ACTOR),eq(M),any())).thenReturn(List.of()))){
   var q=new JdbcMinutesQueries(f.authority,()->mock(ConfigArchiveSource.Snapshot.class),H,new Ref(ArtifactType.PROMPT_CONFIG,"v1",H),new Ref(ArtifactType.MODEL_CONFIG,"v1",H),Task11CombinedInstallationTest.LIMITS);if(installed)q.bindCombined(editor,initial,generation);
   var current=q.current(ACTOR,M);var stored=q.input(ACTOR,M,M);var result=q.candidate(ACTOR,M,M);assertEquals(installed,current.get("eligible"));assertEquals(installed,((Map<String,Object>)stored.get("currentReadiness")).get("eligible"));assertEquals(installed,((Map<String,Object>)result.get("eligibility")).get("canAdopt"));assertEquals("immutable-original",stored.get("manifestJson"));assertEquals("PENDING",((Map<String,Object>)result.get("candidate")).get("state"));
   var acquisitions=mockingDetails(readers.constructed().getFirst()).getInvocations().stream().filter(i->i.getMethod().getName().equals("readOwner")).toList();
   for(var acquisition:acquisitions)assertTrue(acquisition.getArguments()[acquisition.getArguments().length-1] instanceof TranscriptAcquisitionBudget.Ledger,"Each eligibility GET must supply its request ledger");
   if(installed){var predicates=mockingDetails(generation).getInvocations().stream().filter(i->i.getMethod().getName().equals("verifyCurrentReadiness")).toList();for(int n=0;n<2;n++)assertSame(acquisitions.get(n).getArguments()[4],predicates.get(n).getArguments()[3]);var adoption=mockingDetails(saved).getInvocations().stream().filter(i->i.getMethod().getName().equals("verifyAdoptionReadiness")).findFirst().orElseThrow();assertSame(acquisitions.get(2).getArguments()[4],adoption.getArguments()[3]);var pageCall=mockingDetails(pages.constructed().getFirst()).getInvocations().stream().filter(i->i.getMethod().getName().equals("allTaskRows")).findFirst().orElseThrow();assertSame(acquisitions.getFirst().getArguments()[4],pageCall.getArguments()[2]);}
   if(installed){verify(generation,times(2)).verifyCurrentReadiness(eq(ACTOR),eq(M),eq(1L),any());verify(saved).verifyAdoptionReadiness(eq(ACTOR),eq(M),eq(M),any());doThrow(ama.contract.MinutesContracts.fail(FailureCode.CAPABILITY_UNAVAILABLE)).when(generation).verifyCurrentReadiness(eq(ACTOR),eq(M),eq(1L),any());assertEquals(List.of("CAPABILITY_UNAVAILABLE"),q.current(ACTOR,M).get("reasons"));doThrow(new ama.contract.TranscriptContracts.Failure(409,"CANDIDATE_NOT_CURRENT")).when(saved).verifyAdoptionReadiness(eq(ACTOR),eq(M),eq(M),any());assertEquals(List.of("CANDIDATE_NOT_CURRENT"),((Map<String,Object>)q.candidate(ACTOR,M,M).get("eligibility")).get("reasons"));doThrow(new MeetingAccess.AccessDeniedException()).when(generation).verifyCurrentReadiness(eq(ACTOR),eq(M),eq(1L),any());assertThrows(MeetingAccess.AccessDeniedException.class,()->q.current(ACTOR,M));verify(generation,never()).enqueue(any(),anyString(),anyString(),anyLong(),anyString());verify(saved,never()).adopt(any(),anyString(),anyString(),anyLong(),anyString(),anyString(),anyString(),anyString());}
   else{assertEquals(List.of("MINUTES_COMBINED_NOT_INSTALLED"),current.get("reasons"));verifyNoInteractions(generation,saved);}
  }
 }
}
